function validate([num1, num2]) {
  for (const [name, value] of [['num1', num1], ['num2', num2]]) {
    if (typeof value !== 'string' || value.length < 1 || value.length > 10000) return `${name} needs 1 to 10^4 digits.`;
    if (!/^[0-9]+$/.test(value)) return `${name} may contain only digits.`;
    if (value.length > 1 && value[0] === '0') return `${name} cannot have a leading zero.`;
  }
  return null;
}

